import { calculateTotals, money } from './cart.mjs';

const { chefs, dishes, cuisines } = window.HOMEBITE_DATA;
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
  chef:'<path d="M7 14a5 5 0 0 1-1-10 6 6 0 0 1 12 0 5 5 0 0 1-1 10v7H7v-7Z"/><path d="M7 17h10M10 11v3m4-3v3"/>',
  heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  orders:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v3H9zM9 11h6m-6 4h6"/>',
  gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13"/><path d="M12 8H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z"/>',
  pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
  chevron:'<path d="m6 9 6 6 6-6"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  minus:'<path d="M5 12h14"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',
  leaf:'<path d="M20 3C8 2 2 8 5 15c4 8 15 3 15-12Z"/><path d="M3 21 15 9"/>',
  fire:'<path d="M12 3c2 5-4 7-1 10 1-2 3-3 4-5 8 8 3 14-3 14-8 0-10-10-5-14-1 4 1 5 1 5 1-4 4-5 4-10Z"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  verified:'<path d="m12 2 3 2 4 1 1 4 2 3-2 3-1 4-4 1-3 2-3-2-4-1-1-4-2-3 2-3 1-4 4-1Z" fill="currentColor" stroke="none"/><path d="m8 12 3 3 5-6" stroke="white"/>',
  truck:'<path d="M3 5h11v12H3V5Zm11 5h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',
  sliders:'<path d="M4 7h8m4 0h4M4 17h2m4 0h10"/><circle cx="14" cy="7" r="2"/><circle cx="8" cy="17" r="2"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3v.1"/>',
  external:'<path d="M14 3h7v7m0-7L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',
  card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',
  wallet:'<path d="M20 7V4H5a3 3 0 0 0 0 6h16v10H5a3 3 0 0 1-3-3V7"/><path d="M21 13h-5v4h5"/>',
  cash:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 8h1m12 8h1"/>',
  shield:'<path d="m12 3 8 3v6c0 6-8 10-8 10S4 18 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>'
};
const icon = (name, cls = '') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.home}</svg>`;
const chefFor = dish => chefs.find(c => c.id === dish.chefId);
const cuisineName = id => cuisines.find(c => c.id === id)?.name || id;
let storageAvailable = true;
function readStorage(key, fallback) { try { return JSON.parse(localStorage.getItem(`homebite-${key}`)) ?? fallback; } catch { return fallback; } }
const storedCart = readStorage('cart', []);
const storedFavorites = readStorage('favorites', []);
const storedOrders = readStorage('orders', []);
const storedAddress = readStorage('address', {});
const state = {
  page: ['discover','chefs','favorites','orders','offers'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'discover',
  cuisine:'all', filter:'all', sort:'recommended', search:'', expanded:false,
  cart: Array.isArray(storedCart) ? storedCart.filter(x => x && dishes.some(d => d.id === x.id) && Number.isInteger(x.qty) && x.qty > 0).map(x => ({id:x.id,qty:Math.min(x.qty,20)})) : [],
  favorites: Array.isArray(storedFavorites) ? storedFavorites.filter(id => dishes.some(d => d.id === id)) : [],
  orders: Array.isArray(storedOrders) ? storedOrders.filter(o => o && Array.isArray(o.items) && o.items.length && o.items.every(i=>i && typeof i.name==='string' && Number.isInteger(i.qty) && i.qty>0) && Number.isFinite(o.total) && typeof o.id === 'string') : [],
  address: storedAddress && typeof storedAddress === 'object' && !Array.isArray(storedAddress) ? storedAddress : {},
  promo: ['FIRSTBITE','FREEDELIVERY'].includes(readStorage('promo','')) ? readStorage('promo','') : '',
  payment:'card', checkoutDraft:{}, detailQty:1, detailId:null, ordering:false, toastTimer:null
};
function persist(key) { try { localStorage.setItem(`homebite-${key}`, JSON.stringify(state[key])); } catch { if(storageAvailable){storageAvailable=false;toast('Storage is unavailable. Your changes will last for this visit.');} } }
function toast(message){ $('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400); }
function image(src, alt, attrs = ''){ return `<img src="${esc(src)}" alt="${esc(alt)}" ${attrs} loading="lazy">`; }
function chefAvatar(chef, attrs=''){ return image(chef.avatar, chef.name, attrs); }
function rating(value, suffix=''){return `<span class="rating">${icon('star')}${value}${suffix ? `<span>${esc(suffix)}</span>`:''}</span>`;}
function totals(){return calculateTotals(state.cart,dishes,chefs,state.promo);}
function updateCartCount(){ $('#cart-count').textContent=state.cart.reduce((sum,i)=>sum+i.qty,0); }
function updateAddress(){ $('#address-label').textContent=state.address.area || 'Downtown, New York'; }
function nav(){
  $('#navigation').innerHTML=[['discover','home','Discover'],['chefs','chef','Home chefs'],['favorites','heart','Favorites'],['orders','orders','My orders'],['offers','gift','Offers & rewards']].map(([id,i,label])=>`<a class="nav-link ${state.page===id?'active':''}" href="#${id}" ${state.page===id?'aria-current="page"':''} title="${label}">${icon(i)}<span>${label}</span>${id==='offers'?'<span class="nav-new">NEW</span>':''}</a>`).join('');
}
function foodCard(d){const chef=chefFor(d);const saved=state.favorites.includes(d.id);const qty=state.cart.find(i=>i.id===d.id)?.qty;return `<article class="food-card">
  <div class="food-photo-wrap"><button class="food-photo-button" data-action="dish" data-id="${d.id}" aria-label="View ${esc(d.name)}">${image(d.image,d.name,'class="food-photo"')}</button>${d.tag?`<span class="food-tag ${d.vegetarian?'green':''}">${icon(d.vegetarian?'leaf':'fire')}${esc(d.tag)}</span>`:''}<button class="favorite-button ${saved?'saved':''}" data-action="favorite" data-id="${d.id}" aria-label="${saved?'Remove':'Save'} ${esc(d.name)} ${saved?'from':'to'} favorites" aria-pressed="${saved}">${icon('heart')}</button><span class="photo-time">${icon('clock')}${esc(chef.time)} min</span></div>
  <div class="food-card-body"><button class="card-chef" data-action="chef" data-id="${chef.id}">${chefAvatar(chef)}${esc(chef.kitchen)}<span class="verified">${icon('verified')}</span></button><div class="card-title-row"><button class="card-title" data-action="dish" data-id="${d.id}">${esc(d.name)}</button>${rating(d.rating)}</div><p class="card-description">${esc(d.description)}</p><div class="card-bottom"><span class="card-price">${money(d.price)}<small>/ serving</small></span><button class="add-button ${qty?'has-items':''}" data-action="add" data-id="${d.id}" aria-label="Add ${esc(d.name)} to cart">${qty || icon('plus')}</button></div></div></article>`;}
function chefCard(chef){return `<button class="chef-card" data-action="chef" data-id="${chef.id}"><span class="chef-avatar-wrap">${chefAvatar(chef)}<span class="verified">${icon('verified')}</span></span><span><h3>${esc(chef.kitchen)}</h3><p>${esc(chef.name)} · ${esc(cuisineName(chef.cuisine))}</p>${rating(chef.rating,`(${chef.reviews} reviews)`)}</span></button>`;}
function filters(){return `<div class="filters-row"><div class="filter-chips" aria-label="Filter meals">${[['all','sliders','All meals'],['rating','star','Top rated'],['vegetarian','leaf','Vegetarian'],['budget','wallet','Under $15'],['free','truck','Free delivery']].map(([id,i,label])=>`<button class="chip ${state.filter===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${state.filter===id}">${icon(i)}${label}</button>`).join('')}</div><label class="sort-wrap">Sort by:<select id="sort" aria-label="Sort meals"><option value="recommended" ${state.sort==='recommended'?'selected':''}>Recommended</option><option value="price-low" ${state.sort==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${state.sort==='price-high'?'selected':''}>Price: high to low</option><option value="rating" ${state.sort==='rating'?'selected':''}>Highest rated</option></select></label></div>`;}
function filteredDishes(){let result=dishes.filter(d=>{
  const chef=chefFor(d);const q=state.search.toLowerCase().trim();
  return (state.cuisine==='all'||d.cuisine.toLowerCase()===state.cuisine.toLowerCase())&&(!q||`${d.name} ${d.description} ${d.cuisine} ${cuisineName(d.cuisine)} ${chef.name} ${chef.kitchen}`.toLowerCase().includes(q))&&(state.filter!=='vegetarian'||d.vegetarian)&&(state.filter!=='rating'||d.rating>=4.8)&&(state.filter!=='budget'||d.price<15)&&(state.filter!=='free'||chef.deliveryFee===0);
});
  if(state.sort==='price-low')result.sort((a,b)=>a.price-b.price);else if(state.sort==='price-high')result.sort((a,b)=>b.price-a.price);else if(state.sort==='rating')result.sort((a,b)=>b.rating-a.rating);else result.sort((a,b)=>Number(b.popular)-Number(a.popular));return result;
}
function emptyState(title,description,i='search',action='browse',label='Explore homemade meals'){return `<div class="empty-state no-results"><div class="empty-icon">${icon(i)}</div><h2>${title}</h2><p>${description}</p><button class="primary-button" data-action="${action}">${label}</button></div>`;}
function menuMarkup(){const all=filteredDishes();const limited=!state.expanded&&!state.search&&state.cuisine==='all'&&state.filter==='all';const shown=limited?all.slice(0,4):all;return `${state.search?`<p class="search-result-note">${all.length} ${all.length===1?'meal':'meals'} found for <strong>“${esc(state.search)}”</strong></p>`:''}${filters()}<div class="food-grid ${limited?'':'expanded'}">${shown.length?shown.map(foodCard).join(''):emptyState('Nothing on the menu just yet','Try another cuisine or clear your filters to discover something delicious.','search','clear-filters','Clear filters')}</div>${limited&&all.length>4?'<div class="load-more-wrap"><button class="secondary-button" data-action="view-all">Explore all meals</button></div>':''}`;}
function discover(){return `<div class="welcome-line"><p>Good food starts at home. <strong>Let’s find your next favorite.</strong></p><span class="local-badge">${icon('pin')}Made in your neighborhood</span></div>
  <section class="hero" aria-label="Homemade food delivered"><div class="hero-content"><div class="eyebrow">${icon('home')}FROM REAL KITCHENS, WITH LOVE</div><h1>A little taste<br>of <span>home.</span></h1><p class="hero-description">Heartwarming meals from passionate home chefs.<br>Made fresh, with love. Delivered to your door.</p><button class="primary-button" data-action="explore">Find your comfort food</button><div class="hero-social"><div class="mini-avatars">${chefs.slice(0,3).map(c=>chefAvatar(c)).join('')}</div><span>Good food. <strong>Great home chefs.</strong> One happy community.</span></div></div>
  <div class="hero-art" aria-hidden="true"><div class="hero-circle"></div><img class="hero-food" src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=85" alt="" fetchpriority="high"><svg class="hero-leaf" viewBox="0 0 70 70"><path d="M34 62C10 47 16 15 52 5c8 29-2 45-18 57Z" fill="#71935c"/><path d="M28 70 43 22m-9 29-12-8m16-5 14-7" stroke="#507344" stroke-width="2" fill="none"/></svg><svg class="hero-leaf bottom" viewBox="0 0 70 70"><path d="M34 62C10 47 16 15 52 5c8 29-2 45-18 57Z" fill="#71935c"/><path d="M28 70 43 22m-9 29-12-8m16-5 14-7" stroke="#507344" stroke-width="2" fill="none"/></svg><div class="hero-tomato"></div><span class="hero-tag">${icon('leaf')}Freshly made, always</span><div class="floating-review">${chefAvatar(chefs[0])}<div><strong>A little love in every bite</strong><div class="stars">★★★★★</div><small>From our kitchen to your table</small></div></div></div></section>
  <section class="section" aria-labelledby="cuisine-heading"><div class="section-heading"><h2 id="cuisine-heading">What are you craving?</h2><button class="section-link" data-action="clear-filters">Explore all cuisines ${icon('external')}</button></div><div class="cuisine-list">${[{id:'all',name:'All cuisines',emoji:'🍽️'},...cuisines.filter(c=>c.id!=='all')].map(c=>`<button class="cuisine-button ${state.cuisine===c.id?'active':''}" data-action="cuisine" data-id="${c.id}" aria-pressed="${state.cuisine===c.id}"><span class="cuisine-emoji" aria-hidden="true">${c.emoji}</span><span>${esc(c.name)}</span></button>`).join('')}</div></section>
  <section class="section menu-section" id="meals" aria-labelledby="meals-heading"><div class="section-heading"><div><h2 id="meals-heading">Made nearby. Loved locally.</h2><p>Fresh favorites from the kitchens around you</p></div><button class="section-link" data-action="view-all">View all meals ${icon('external')}</button></div><div id="menu-content">${menuMarkup()}</div></section>
  <section class="section chef-section"><div class="section-heading"><div><h2>Meet the hands behind your food.</h2><p>Real people, family recipes, and a whole lot of heart</p></div><a class="section-link" href="#chefs">Meet all chefs ${icon('external')}</a></div><div class="chef-grid">${chefs.slice(0,4).map(chefCard).join('')}</div></section>
  <section class="bottom-promo"><div class="promo-icon">${icon('gift')}</div><div><h3>Your first bite is a little sweeter.</h3><p>Enjoy 20% off your first homemade meal. Good food is even better shared.</p></div><button class="promo-code-button" data-action="promo" data-id="FIRSTBITE">FIRSTBITE<span>Tap to apply</span></button></section>`;}
function viewHeader(eyebrow,title,description){return `<div class="view-header"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>`;}
function chefsView(){return viewHeader('GOOD FOOD HAS A GOOD STORY','Meet your neighborhood cooks.','Family recipes, fresh ingredients, and a seat at everyone’s table.')+`<div class="large-chef-grid">${chefs.map(c=>`<article class="large-chef-card">${image(dishes.find(d=>d.chefId===c.id)?.image||dishes[0].image,`${c.cuisine} food from ${c.kitchen}`,'class="chef-cover"')}<div class="large-chef-body">${chefAvatar(c)}<h3>${esc(c.kitchen)}</h3><div class="chef-name">With ${esc(c.name)} · ${esc(cuisineName(c.cuisine))}</div><p>${esc(c.bio)}</p><div class="chef-meta">${rating(c.rating,`(${c.reviews})`)}<span>${esc(c.time)} min</span><span>${c.deliveryFee===0?'Free delivery':money(c.deliveryFee)+' delivery'}</span></div><button class="secondary-button" data-action="chef" data-id="${c.id}">Explore the kitchen</button></div></article>`).join('')}</div>`;}
function favoritesView(){const saved=dishes.filter(d=>state.favorites.includes(d.id));return viewHeader('A LITTLE COLLECTION OF COMFORT','Your favorite bites.','The meals you love, all in one delicious place.')+(saved.length?`<div class="food-grid expanded">${saved.map(foodCard).join('')}</div>`:emptyState('Good taste deserves saving','Tap the heart on any meal to keep it here for your next craving.','heart'));}
const paymentLabels={card:'Demo Visa •••• 4242',paypal:'PayPal (demo)',apple:'Apple Pay (demo)',cash:'Cash on delivery'};
function orderCard(o){const date=new Date(o.createdAt);return `<article class="order-card"><div class="order-top"><div><h3>Order #${esc(o.id)}</h3><p>${Number.isNaN(date.getTime())?'Demo order':date.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · ${esc(o.kitchens)} ${o.kitchens===1?'home kitchen':'home kitchens'}</p></div><span class="order-status">Demo order confirmed</span></div><p class="order-items">${o.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(' · ')}</p><div class="order-progress"><span class="order-step active">Confirmed</span><span class="order-step">Cooking</span><span class="order-step">On the way</span><span class="order-step">Enjoy!</span></div><div class="order-bottom"><span>${esc(paymentLabels[o.payment]||o.payment)}<br>${esc(o.address?.street||'Demo address')}</span><strong>${money(o.total)}</strong></div></article>`;}
function ordersView(){return viewHeader('HAPPINESS, ON ITS WAY','Your homemade moments.','Keep track of the meals that made your day.')+(state.orders.length?`<div class="demo-note" style="margin-bottom:20px">${icon('info')}These are project demo orders. No seller is contacted, no payment is taken, and no delivery is dispatched.</div>${state.orders.map(orderCard).join('')}`:emptyState('Your first bite is waiting','Place a demo order and follow your homemade favorites here.','bag'));}
function offersView(){return viewHeader('A LITTLE SOMETHING EXTRA','Good food. Great little perks.','Because your next homemade meal deserves a treat.')+`<div class="offer-grid"><article class="offer-card"><div class="eyebrow">A WARM WELCOME</div><div class="offer-big">20% off</div><h2>Your first taste of HomeBite</h2><p>Find a new favorite and enjoy a little something off your meal. The perfect excuse to try that dish you’ve been eyeing.</p><button class="primary-button" data-action="promo" data-id="FIRSTBITE">Apply FIRSTBITE</button><small>20% off food, up to $10. One offer per order. Demo promotion.</small></article><article class="offer-card"><div class="eyebrow">FROM OUR DOOR TO YOURS</div><div class="offer-big">Free delivery</div><h2>More comfort, fewer fees</h2><p>Let us take care of the delivery fee, even when you pick meals from more than one home kitchen.</p><button class="secondary-button" data-action="promo" data-id="FREEDELIVERY">Apply FREEDELIVERY</button><small>Delivery fees waived. Service fee applies. One offer per order.</small></article></div>`;}
function render(){nav();$('#main').innerHTML=({discover,chefs:chefsView,favorites:favoritesView,orders:ordersView,offers:offersView}[state.page])();updateCartCount();updateAddress();}
function renderMenu(){if($('#menu-content'))$('#menu-content').innerHTML=menuMarkup();}
function go(page){if(location.hash!==`#${page}`)location.hash=page;else{state.page=page;render();}}
function browse(){state.cuisine='all';state.filter='all';state.search='';state.expanded=false;$('#search').value='';go('discover');}
function addToCart(id,qty=1){const dish=dishes.find(d=>d.id===id);if(!dish)return;const existing=state.cart.find(i=>i.id===id);if((existing?.qty||0)+qty>20){toast('You can add up to 20 servings of each meal.');return;}if(existing)existing.qty+=qty;else state.cart.push({id,qty});persist('cart');updateCartCount();if(state.page==='discover')renderMenu();if(state.page==='favorites')render();toast(`${dish.name} added to your cart`);}
function changeQuantity(id,delta){const item=state.cart.find(i=>i.id===id);if(!item)return;item.qty=Math.min(20,item.qty+delta);state.cart=state.cart.filter(i=>i.qty>0);persist('cart');renderCart();updateCartCount();if(state.page==='discover')renderMenu();else if(state.page==='favorites')render();}
function modalOpen(content,kind=''){const modal=$('#modal');modal.className=kind;modal.innerHTML=content;if(!modal.open)modal.showModal();}
function modalHead(title){return `<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function openDish(id){const d=dishes.find(x=>x.id===id);if(!d)return;state.detailId=id;state.detailQty=1;const chef=chefFor(d);modalOpen(`<div class="dish-image-wrap">${image(d.image,d.name,'class="dish-modal-image"')}<button class="close-button" data-action="close-modal" aria-label="Close dish details">${icon('close')}</button></div><div class="dish-modal-body"><button class="card-chef" data-action="chef" data-id="${chef.id}">${chefAvatar(chef)}${esc(chef.kitchen)} ${icon('verified')}</button><h2 id="modal-title">${esc(d.name)}</h2>${rating(d.rating)}<p>${esc(d.description)}</p><div class="dish-tags"><span>${esc(cuisineName(d.cuisine))}</span>${d.vegetarian?'<span>Vegetarian</span>':''}${d.spicy?'<span>Spicy</span>':''}<span>${esc(chef.time)} min</span></div><div class="demo-note">${icon('info')}Sample project menu. Ingredients and allergens vary by dish; this demo does not accept real food orders.</div><div class="dish-modal-footer"><div class="quantity-control"><button data-action="detail-qty" data-delta="-1" aria-label="Decrease servings">${icon('minus')}</button><span id="detail-qty">1</span><button data-action="detail-qty" data-delta="1" aria-label="Increase servings">${icon('plus')}</button></div><button class="primary-button" data-action="add-detail" id="detail-add">Add to cart · ${money(d.price)}</button></div></div>`);}
function openChef(id){const c=chefs.find(x=>x.id===id);if(!c)return;modalOpen(modalHead(c.kitchen)+`<div class="modal-body"><div class="chef-profile-header">${chefAvatar(c)}<div><h3>${esc(c.name)}</h3><p>${esc(cuisineName(c.cuisine))} home chef · ${rating(c.rating)}</p></div></div><p>${esc(c.bio)}</p><div class="chef-meta"><span>${icon('clock')} ${esc(c.time)} min</span><span>${c.deliveryFee===0?'Free delivery':money(c.deliveryFee)+' delivery'}</span></div><h3>Made with love, just for you</h3>${dishes.filter(d=>d.chefId===id).map(d=>`<div class="chef-menu-row">${image(d.image,d.name)}<div><h4>${esc(d.name)}</h4><p>${money(d.price)} ${d.vegetarian?'· Vegetarian':''}</p></div><button class="add-button" data-action="add" data-id="${d.id}" aria-label="Add ${esc(d.name)}">${icon('plus')}</button></div>`).join('')}<div class="demo-note" style="margin-top:20px">${icon('info')}This is a fictional home chef created for the HomeBite project.</div></div>`);}
function totalsMarkup(t){return `<div class="totals-line"><span>Food subtotal</span><span>${money(t.subtotal)}</span></div><div class="totals-line"><span>Delivery ${t.kitchens>1?`(${t.kitchens} kitchens)`:''}</span><span>${t.delivery===0?'Free':money(t.delivery)}</span></div><div class="totals-line"><span>Service fee</span><span>${money(t.service)}</span></div>${t.discount?`<div class="totals-line discount"><span>FIRSTBITE discount</span><span>−${money(t.discount)}</span></div>`:''}<div class="totals-line total-line"><span>Total</span><span>${money(t.total)}</span></div>`;}
function renderCart(){const t=totals();$('#cart-dialog').innerHTML=`<div class="drawer-layout"><div class="modal-header"><div><h2 id="cart-title">Your happy little cart</h2><p class="cart-subtitle">${t.items.reduce((s,i)=>s+i.qty,0)} servings of homemade goodness</p></div><button class="close-button" data-action="close-cart" aria-label="Close cart">${icon('close')}</button></div><div class="drawer-content">${t.items.length?`<div class="demo-note">${icon('home')}Made fresh by ${t.kitchens} ${t.kitchens===1?'home kitchen':'home kitchens'}. Delivery is charged per kitchen.</div>${t.items.map(i=>`<div class="cart-item">${image(i.image,i.name)}<div class="cart-item-info"><h3>${esc(i.name)}</h3><p>${esc(chefFor(i).kitchen)}</p><strong>${money(i.price*i.qty)}</strong></div><div class="cart-item-right"><button class="remove-button" data-action="remove" data-id="${i.id}" aria-label="Remove ${esc(i.name)}">Remove</button><div class="quantity-control"><button data-action="quantity" data-id="${i.id}" data-delta="-1" aria-label="Decrease ${esc(i.name)} quantity">${icon('minus')}</button><span>${i.qty}</span><button data-action="quantity" data-id="${i.id}" data-delta="1" aria-label="Increase ${esc(i.name)} quantity" ${i.qty===20?'disabled':''}>${icon('plus')}</button></div></div></div>`).join('')}`:`<div class="cart-empty">${emptyState('A little empty, a lot of possibility','Find something homemade to make your day.','bag','close-cart','Keep exploring')}</div>`}</div>${t.items.length?`<div class="drawer-footer">${state.promo?`<div class="promo-applied"><span>${icon('check')} ${state.promo} applied</span><button data-action="remove-promo" aria-label="Remove promo code">${icon('close')}</button></div>`:`<form id="promo-form" class="promo-entry"><input name="promo" placeholder="Got a promo code?" aria-label="Promo code" maxlength="30"><button type="submit">Apply</button></form>`}${totalsMarkup(t)}<button class="primary-button" data-action="checkout"><span>Continue to checkout</span>${money(t.total)}</button><small>Project demo · No real payments or deliveries</small></div>`:''}</div>`;}
function openCart(){if($('#modal').open)$('#modal').close();renderCart();if(!$('#cart-dialog').open)$('#cart-dialog').showModal();}
function addressFields(value,checkout=false){return `<div class="form-row"><label class="form-field"><span>Full name</span><input name="name" autocomplete="name" required maxlength="70" value="${esc(value.name||'')}" placeholder="Jamie Davis"></label><label class="form-field"><span>Phone number</span><input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{7,20}" maxlength="20" value="${esc(value.phone||'')}" placeholder="+1 212 555 0100"></label></div><label class="form-field"><span>Street address</span><input name="street" autocomplete="street-address" required minlength="5" maxlength="140" value="${esc(value.street||'')}" placeholder="123 Spring Street, Apt 4"></label><div class="form-row"><label class="form-field"><span>City / neighborhood</span><input name="area" autocomplete="address-level2" required maxlength="80" value="${esc(value.area||'')}" placeholder="Downtown, New York"></label><label class="form-field"><span>ZIP / postal code</span><input name="zip" autocomplete="postal-code" required pattern="[A-Za-z0-9 -]{3,12}" maxlength="12" value="${esc(value.zip||'')}" placeholder="10012"></label></div>${checkout?`<label class="form-field"><span>Delivery note <span style="color:#a3a99a;font-weight:400">(optional)</span></span><textarea name="note" maxlength="250" placeholder="Apartment, gate code, or a little note for delivery">${esc(value.note||'')}</textarea></label>`:''}`;}
function openAddress(){modalOpen(modalHead('Where should we bring the good food?')+`<form id="address-form" class="modal-body">${addressFields(state.address)}<button class="primary-button wide-button" type="submit">Save delivery address</button><p style="font-size:11px;margin-top:13px">Demo details are saved only in this browser. You can use a fictional address.</p></form>`);}
function captureDraft(){const form=$('#checkout-form');if(form){const data=new FormData(form);state.checkoutDraft=Object.fromEntries(data);state.payment=String(data.get('payment')||'card');}}
function renderCheckout(){const t=totals();if(!t.items.length){renderCart();return;}const value={...state.address,...state.checkoutDraft};$('#cart-dialog').innerHTML=`<div class="drawer-layout"><div class="modal-header"><div><h2 id="cart-title">One step closer to home.</h2><p class="cart-subtitle">Let’s make your next meal a good one.</p></div><button class="close-button" data-action="close-cart" aria-label="Close checkout">${icon('close')}</button></div><div class="drawer-content"><button class="back-button" data-action="back-cart">${icon('chevron')}Back to your cart</button><div class="checkout-summary"><strong>Fresh from ${t.kitchens} ${t.kitchens===1?'home kitchen':'home kitchens'}</strong><p>Estimated demo delivery: 30–45 minutes</p></div><form id="checkout-form"><section class="checkout-section"><h3>1. Your delivery details</h3>${addressFields(value,true)}</section><section class="checkout-section"><h3>2. How would you like to pay?</h3>${[['card','card','Credit or debit card','Demo Visa · 4242'],['paypal','wallet','PayPal','Online payment'],['apple','wallet','Apple Pay','Digital wallet'],['cash','cash','Cash on delivery','Pay when it arrives']].map(([id,i,label,sub])=>`<label class="payment-option"><input type="radio" name="payment" value="${id}" ${state.payment===id?'checked':''} required>${icon(i)}<span>${label}</span><small>${sub}</small></label>`).join('')}<p class="checkout-payment-note">All payment methods are simulated. No account connection or real card details are needed.</p></section></form><div class="demo-note">${icon('shield')}This is a project checkout. No real payment, food preparation, or delivery takes place.</div></div><div class="drawer-footer">${totalsMarkup(t)}<button class="primary-button" type="submit" form="checkout-form" id="place-order"><span>Place demo order</span>${money(t.total)}</button><small>By continuing, you’re placing a simulated project order.</small></div></div>`;}
function applyPromo(code){const normalized=code.trim().toUpperCase();if(!['FIRSTBITE','FREEDELIVERY'].includes(normalized)){toast('That code isn’t on the menu. Try FIRSTBITE or FREEDELIVERY.');return;}if(normalized==='FIRSTBITE'&&state.orders.length){toast('FIRSTBITE is for your first order. Try FREEDELIVERY instead.');return;}state.promo=normalized;persist('promo');toast(`${normalized} applied — your next meal just got sweeter.`);if($('#cart-dialog').open)renderCart();}
function submitOrder(form){if(state.ordering)return;const data=Object.fromEntries(new FormData(form));for(const key of ['name','phone','street','area','zip']){if(!String(data[key]||'').trim()){form.elements[key].setCustomValidity('Please enter your delivery details.');form.elements[key].reportValidity();return;}}const t=totals();if(!t.items.length){renderCart();return;}state.ordering=true;const button=$('#place-order');button.disabled=true;button.textContent='Confirming your demo order…';state.address=Object.fromEntries(['name','phone','street','area','zip'].map(k=>[k,data[k].trim()]));state.payment=data.payment;const order={id:'HB-'+crypto.randomUUID().slice(0,6).toUpperCase(),createdAt:new Date().toISOString(),items:t.items.map(i=>({id:i.id,name:i.name,qty:i.qty,price:i.price,chefId:i.chefId})),...Object.fromEntries(['subtotal','delivery','service','discount','total','kitchens'].map(k=>[k,t[k]])),promo:state.promo,payment:state.payment,address:{...state.address,note:String(data.note||'').trim()}};state.orders.unshift(order);state.cart=[];state.promo='';state.checkoutDraft={};['orders','cart','promo','address'].forEach(persist);updateCartCount();updateAddress();render();state.ordering=false;$('#cart-dialog').innerHTML=`<div class="drawer-layout"><div class="modal-header"><h2 id="cart-title">A little happiness, confirmed.</h2><button class="close-button" data-action="close-cart" aria-label="Close order confirmation">${icon('close')}</button></div><div class="drawer-content"><div class="success-state"><div class="success-check">${icon('check')}</div><h3>You’ve got great taste!</h3><p>Your demo order is confirmed.<br>Good food always feels like coming home.</p><div class="receipt"><div class="totals-line"><span>Order number</span><strong>${order.id}</strong></div><div class="totals-line"><span>Payment method</span><span>${esc(paymentLabels[order.payment])}</span></div><div class="totals-line"><span>${order.payment==='cash'?'Demo amount due':'Demo total'}</span><strong>${money(order.total)}</strong></div></div><div class="demo-note">${icon('info')}Nothing has been charged and no delivery is on its way. This order demonstrates the complete HomeBite experience.</div><button class="primary-button wide-button" data-action="view-orders">View my orders</button><button class="secondary-button wide-button" style="margin-top:10px" data-action="close-cart">Keep exploring</button></div></div></div>`;}
function help(){modalOpen(modalHead('A little help, right here.')+`<div class="modal-body"><p>Everything you need to know about your HomeBite project.</p><details class="faq-item" open><summary>Can I place a real order?</summary><p>HomeBite is an interactive project demo. The chefs, menus, reviews, delivery estimates, and order status are sample content. No real food is ordered.</p></details><details class="faq-item"><summary>How do online payments work?</summary><p>Choose credit or debit card, PayPal, Apple Pay, or cash at checkout. Every method is simulated, so no real account or card details are required and no money is charged.</p></details><details class="faq-item"><summary>Can I order from different kitchens?</summary><p>Yes. Each kitchen’s delivery fee is added once per order, regardless of how many meals you choose. A $0.99 service fee applies per order.</p></details><details class="faq-item"><summary>How do discounts work?</summary><p>FIRSTBITE saves 20% on the food subtotal, up to $10, on your first demo order. FREEDELIVERY removes delivery fees. You can use one code per order.</p></details><details class="faq-item"><summary>Where is my information saved?</summary><p>Your cart, favorites, delivery address, and demo orders stay in this browser’s local storage. They are not sent to a server.</p></details></div>`);}
function profile(){modalOpen(modalHead('Your little corner of HomeBite')+`<div class="modal-body"><div class="chef-profile-header"><div class="profile-button" style="width:55px;height:55px;display:grid;place-items:center">JD</div><div><h3>${esc(state.address.name||'Hello, food lover!')}</h3><p>HomeBite community · Demo account</p></div></div><p>You have ${state.favorites.length} favorite meals and ${state.orders.length} homemade moments saved in this browser.</p><button class="secondary-button wide-button" style="margin-top:20px" data-action="address">${icon('pin')} Manage delivery address</button><button class="secondary-button wide-button" style="margin-top:10px" data-action="view-orders">${icon('orders')} View order history</button><div class="demo-note" style="margin-top:20px">${icon('info')}This is a local demo profile. Sign-in is not required.</div></div>`);}
function becomeChef(){modalOpen(modalHead('Good food starts in your kitchen.')+`<form id="chef-form" class="modal-body"><p style="margin-bottom:20px">Share your signature dish and tell us a little about the kitchen behind it.</p><label class="form-field"><span>Your name</span><input name="name" required maxlength="70" placeholder="Your name"></label><label class="form-field"><span>Kitchen name</span><input name="kitchen" required maxlength="70" placeholder="e.g. The Sunday Kitchen"></label><label class="form-field"><span>Your signature cuisine</span><select name="cuisine">${cuisines.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></label><label class="form-field"><span>Your signature dish</span><input name="dish" required maxlength="90" placeholder="The meal everyone asks you to make"></label><div class="demo-note">${icon('info')}A project demo application. Your details are not sent to anyone.</div><button class="primary-button wide-button" type="submit">Preview my kitchen application</button></form>`);}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const {action,id,delta}=button.dataset;
 switch(action){
 case 'cart':openCart();break;
 case 'close-cart':captureDraft();$('#cart-dialog').close();break;
 case 'close-modal':$('#modal').close();break;
 case 'dish':openDish(id);break;
 case 'chef':openChef(id);break;
 case 'add':addToCart(id);break;
 case 'favorite':{const saved=state.favorites.includes(id);state.favorites=saved?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist('favorites');if(state.page==='discover')renderMenu();else render();toast(saved?'Removed from your favorites':'Saved a little comfort for later');break;}
 case 'cuisine':{state.cuisine=id;state.expanded=true;document.querySelectorAll('.cuisine-button').forEach(el=>{el.classList.toggle('active',el.dataset.id===id);el.setAttribute('aria-pressed',el.dataset.id===id)});renderMenu();break;}
 case 'filter':state.filter=id;state.expanded=true;renderMenu();break;
 case 'clear-filters':state.cuisine='all';state.filter='all';state.search='';state.expanded=false;state.sort='recommended';$('#search').value='';render();break;
 case 'browse':if($('#cart-dialog').open)$('#cart-dialog').close();if($('#modal').open)$('#modal').close();browse();break;
 case 'explore':case 'view-all':state.expanded=true;renderMenu();$('#meals')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'quantity':changeQuantity(id,Number(delta));break;
 case 'remove':state.cart=state.cart.filter(x=>x.id!==id);persist('cart');renderCart();updateCartCount();if(state.page==='discover')renderMenu();else if(state.page==='favorites')render();break;
 case 'detail-qty':{state.detailQty=Math.max(1,Math.min(20,state.detailQty+Number(delta)));$('#detail-qty').textContent=state.detailQty;$('#detail-add').textContent=`Add to cart · ${money(dishes.find(d=>d.id===state.detailId).price*state.detailQty)}`;break;}
 case 'add-detail':addToCart(state.detailId,state.detailQty);$('#modal').close();break;
 case 'address':openAddress();break;
 case 'promo':applyPromo(id);break;
 case 'remove-promo':state.promo='';persist('promo');renderCart();break;
 case 'checkout':renderCheckout();break;
 case 'back-cart':captureDraft();renderCart();break;
 case 'view-orders':if($('#modal').open)$('#modal').close();if($('#cart-dialog').open)$('#cart-dialog').close();go('orders');break;
 case 'help':help();break;
 case 'profile':profile();break;
 case 'become-chef':becomeChef();break;
 case 'about':modalOpen(modalHead('HomeBite, made for a project.')+`<div class="modal-body"><p>A little taste of home, wherever you are. HomeBite brings the familiar ease of a delivery app to the warmth of homemade food.</p><h3>Built to explore</h3><ul><li>Eight fictional home chefs and diverse cuisine menus</li><li>Search, dietary filters, favorites, and meal details</li><li>A cart, promo codes, and delivery details</li><li>Simulated online payments and cash on delivery</li><li>Order history saved in your browser</li></ul><div class="demo-note">${icon('info')}All sellers, reviews, delivery estimates, and orders are demo content. Photographs are illustrative and provided by Unsplash. No real purchases are supported.</div></div>`);break;
 }
});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();
 if(form.id==='promo-form')applyPromo(new FormData(form).get('promo')||'');
 if(form.id==='address-form'){const values=Object.fromEntries(new FormData(form));const blank=Object.keys(values).find(k=>!values[k].trim());if(blank){form.elements[blank].setCustomValidity('Please enter your delivery details.');form.elements[blank].reportValidity();return;}state.address=Object.fromEntries(Object.entries(values).map(([k,v])=>[k,v.trim()]));state.checkoutDraft={};persist('address');updateAddress();$('#modal').close();toast('Your delivery address is saved.');}
 if(form.id==='checkout-form')submitOrder(form);
 if(form.id==='chef-form'){const data=Object.fromEntries(new FormData(form));const blank=['name','kitchen','dish'].find(k=>!data[k]?.trim());if(blank){form.elements[blank].setCustomValidity('Please fill in this field.');form.elements[blank].reportValidity();return;}modalOpen(modalHead('There’s a place for your kitchen.')+`<div class="modal-body"><div class="success-state"><div class="success-check">${icon('chef')}</div><h3>${esc(data.kitchen)}</h3><p>Chef ${esc(data.name)} · ${esc(data.cuisine)}<br>Signature dish: ${esc(data.dish)}</p><div class="demo-note" style="margin-top:24px">${icon('check')}Your demo application preview is ready. No application was submitted or shared.</div><button class="primary-button wide-button" data-action="close-modal">Looks delicious</button></div></div>`);}
});
document.addEventListener('input',event=>{if(event.target.setCustomValidity)event.target.setCustomValidity('');});
$('#search').addEventListener('input',event=>{state.search=event.target.value;state.expanded=true;if(state.page!=='discover'){state.page='discover';history.replaceState(null,'','#discover');render();}else renderMenu();});
document.addEventListener('change',event=>{if(event.target.id==='sort'){state.sort=event.target.value;renderMenu();}if(event.target.name==='payment')state.payment=event.target.value;});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);state.page=['discover','chefs','favorites','orders','offers'].includes(page)?page:'discover';render();window.scrollTo({top:0,behavior:'smooth'});});
$('#cart-dialog').addEventListener('cancel',captureDraft);
for(const dialog of [$('#modal'),$('#cart-dialog')])dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom){if(dialog.id==='cart-dialog')captureDraft();dialog.close();}}});
document.addEventListener('error',event=>{const img=event.target;if(img.tagName==='IMG'&&!img.dataset.fallback){img.dataset.fallback='true';img.src='assets/food-placeholder.svg';}},true);
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
render();
